def policy(obs, P):
  x = obs[0]
  y = obs[1]
  vx = obs[2]
  vy = obs[3]
  angle = obs[4]
  ang_v = obs[5]
  leg_left = obs[6]
  leg_right = obs[7]
  angle_targ = np.clip(x * P['k_x'] + vx * P['k_vx'], -P['max_angle'], P['max_angle'])
  hover_targ = abs(x) * P['k_hover'] + P['y_offset']
  if leg_left or leg_right:
    angle_targ = P['leg_angle_targ']
    hover_targ = P['leg_hover_targ']
  angle_err = angle_targ - angle
  angle_todo = angle_err * P['k_ang'] - ang_v * P['k_angv']
  hover_err = hover_targ - y
  hover_todo = hover_err * P['k_h'] - vy * P['k_v']
  if leg_left and leg_right:
    if abs(angle) > P['land_angle_thresh']:
      if angle_todo < 0:
        return 1
      else:
        return 3
    return 0
  if abs(angle_todo) > P['ang_thresh']:
    if angle_todo < 0:
      return 1
    else:
      return 3
  if abs(angle) < P['safe_angle']:
    if hover_todo > P['hover_thresh'] or vy < P['vy_thresh']:
      return 2
  else:
    if hover_todo > P['hover_thresh'] * P['hover_boost']:
      return 2
  return 0
